import pytest
from src.topo import topo_sort


def is_valid_order(order, edges):
    pos = {node: i for i, node in enumerate(order)}
    return all(pos[u] < pos[v] for u, v in edges)


def test_simple_chain():
    order = topo_sort(3, [(0, 1), (1, 2)])
    assert order == [0, 1, 2] or is_valid_order(order, [(0, 1), (1, 2)])


def test_no_edges():
    order = topo_sort(4, [])
    assert sorted(order) == [0, 1, 2, 3]


def test_diamond():
    # 0 -> 1, 0 -> 2, 1 -> 3, 2 -> 3
    order = topo_sort(4, [(0, 1), (0, 2), (1, 3), (2, 3)])
    assert is_valid_order(order, [(0, 1), (0, 2), (1, 3), (2, 3)])
    assert len(order) == 4


def test_cycle_raises():
    with pytest.raises(ValueError):
        topo_sort(3, [(0, 1), (1, 2), (2, 0)])


def test_self_loop_raises():
    with pytest.raises(ValueError):
        topo_sort(2, [(0, 1), (1, 1)])


def test_single_node():
    assert topo_sort(1, []) == [0]


def test_all_nodes_included():
    order = topo_sort(5, [(0, 4), (1, 4), (2, 3), (3, 4)])
    assert len(order) == 5
    assert is_valid_order(order, [(0, 4), (1, 4), (2, 3), (3, 4)])
